1],{"language":481,"code":2260},"en",{"language":2262,"code":2263},"Portuguese","pt",["Ref",481],["Ref",2260],["Ref",2267],["Reactive",2268],{"globals":469,"header":479,"floating_nav":487,"footer":489,"menu":501,"live_feed":502,"news":511,"events":515,"programs":518,"athletics":520,"stats":524,"spotlight":2269,"buttons":526,"our_schools":527,"alert_modal":528,"custom_html":529,"pagination":532,"about":468,"sticky_footer":498,"spotlights":525,"custom_component":530,"media_custom_code":531,"video":542},["Reactive",2270],{},{"cmsAiSettings":2272,"clientId":2275,"searchUUID":2276,"sessionId":2277},["Ref",2273],["Reactive",2274],{"ai_chat_enabled":7,"ai_search_enabled":7,"tasks_enabled":7,"display_ai_chat":7},["Ref",2254],["EmptyRef",1941],["EmptyRef",1941],{"alertBannerConfig":2279,"alertBannerSeparate":2283,"isAlertModalOpen":2404},["Ref",2280],["Reactive",2281],{"content":2282,"enabled":7,"light_box":7,"display_on_all_pages":7},"<p>Massachusetts State Primary Election is today, September 3, 2024. Abington Registered Voters can cast their ballots at Beaver Brook Elementary School at 1 Ralph Hamlin Lane between 7AM - 8PM. </p>",["Ref",2284],["Reactive",2285],[2286,2293,2298,2303,2308,2313,2318,2323,2328,2334,2339,2343,2348,2353,2358,2363,2368,2373,2378,2383,2388,2393,2398],{"id":2287,"secondary_organization_id":22,"secondary_organization_ids":2288,"content":2289,"image":2290,"status":2291,"style":2292,"display_location":1028,"featured":12},14820,[22],"<p>In observance of Veterans Day, <strong>Abington Town Offices are closed on November 11, 2024</strong>. Thank you to all those who have served our country.</p><p>Please note, that there is no trash pick up on 11/11/2024, and all routes will be delayed by one day. </p>",{},"archived","banner",{"id":2294,"secondary_organization_id":22,"secondary_organization_ids":2295,"content":2296,"image":2297,"status":6,"style":2292,"display_location":1028,"featured":12},15997,[22],"<p>Please note, Abington Town Offices will be closed on Friday, July 4 in recognition of Independence Day.</p><p>There will be no trash collection on <span>Friday, July 4. Friday routes will be collected on Saturday, July 5.</span></p>",{"url":79,"alt_text":79},{"id":2299,"secondary_organization_id":22,"secondary_organization_ids":2300,"content":2301,"image":2302,"status":6,"style":2292,"display_location":1028,"featured":12},16843,[22],"<p>Please note our holiday hours:</p><p>Tuesday, December 31: Open 8:30AM - 12 PM and Wednesday, January 1: Closed.<br><br>Trash pick-up is delayed one day for residents with normal pick-ups on Wednesdays, Thursdays, and Fridays.</p>",{"url":79,"alt_text":79},{"id":2304,"secondary_organization_id":22,"secondary_organization_ids":2305,"content":2306,"image":2307,"status":6,"style":2292,"display_location":1028,"featured":12},17421,[22],"<p>SPECIAL ELECTION: JANUARY 25, 2024. Polls are open <span>9AM - 5PM at Beaver Brook Elementary School located at 1 Ralph G Hamlin Way. </span><a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/o/toa/page/ssvt-building-project"><span>Learn more about the ballot question to allow South Shore Vo Tech to build a new school. </span></a></p>",{"url":79,"alt_text":79},{"id":2309,"secondary_organization_id":22,"secondary_organization_ids":2310,"content":2311,"image":2312,"status":6,"style":2292,"display_location":1028,"featured":12},18586,[22],"<p>The Town of Abington Offices are closed on Monday, January 20, 2025, in recognition of Martin Luther King, Jr., Day. Please note, there will be no trash and recycling collection.</p><p>Monday (1/20) routes will be collected on Tuesday, all other routes will be delayed one day.</p>",{"url":79,"alt_text":79},{"id":2314,"secondary_organization_id":22,"secondary_organization_ids":2315,"content":2316,"image":2317,"status":6,"style":2292,"display_location":1028,"featured":12},21540,[22],"<p>In recognition of the Presidents' Day holiday, Abington Town Offices are closed on Monday, February 17, 2025. Trash pick up will be delayed one day for all residents. </p>",{"url":79,"alt_text":79},{"id":2319,"secondary_organization_id":22,"secondary_organization_ids":2320,"content":2321,"image":2322,"status":6,"style":2292,"display_location":1028,"featured":12},24223,[22],"<p>Town Offices will be closed on Monday, April 21, 2025 in recognition of Patriots' Day. Trash and recycling will not be picked up on Monday. The scheduled routes will be delayed by one day. </p>",{"url":79,"alt_text":79},{"id":2324,"secondary_organization_id":22,"secondary_organization_ids":2325,"content":2326,"image":2327,"status":6,"style":2292,"display_location":1028,"featured":12},24282,[22],"<h3 style="text-align: left">Annual Town Election: Saturday, April 26, 2025. Polls are open at Beaver Brook Elementary School from 8AM -6PM. Early Voting is available at the Town Clerk's office during regular business hours. <a target="_self" rel="noopener noreferrer nofollow" href="https://5il.co/3do3y">Review a sample ballot.</a></h3>",{"url":79,"alt_text":79},{"id":2329,"secondary_organization_id":22,"secondary_organization_ids":2330,"content":2331,"image":2332,"status":6,"style":2292,"display_location":2333,"featured":12},25028,[22],"<h2 style="text-align: left">BOIL WATER ORDER LIFTED AS OF MAY 18, 2025.</h2><p style="text-align: left">Customers of Abington/Rockland Joint Water Works were notified on 5/16/2025 of a problem with our drinking water and were advised to boil water prior to consumption. We are pleased to report that the problem has been corrected and that it is no longer necessary to boil water prior to consumption. We apologize for any inconvenience and thank you for your patience. </p><p style="text-align: left"><a target="_blank" rel="noopener noreferrer nofollow" href="https://5il.co/3ggcb"><strong>Read the full notice from ARJWW.</strong></a></p><p style="text-align: left"></p>",{"url":79,"alt_text":79},"all_pages",{"id":2335,"secondary_organization_id":22,"secondary_organization_ids":2336,"content":2337,"image":2338,"status":6,"style":2292,"display_location":1028,"featured":12},25311,[22],"<p>The Town of Abington Offices will be closed on Monday, May 26, 2025 in recognition of Memorial Day. Trash pick-up will be delayed by one day. </p>",{"url":79,"alt_text":79},{"id":2340,"secondary_organization_id":22,"secondary_organization_ids":2341,"content":2316,"image":2342,"status":1967,"style":2292,"display_location":1028,"featured":12},26147,[22],{"url":79,"alt_text":79},{"id":2344,"secondary_organization_id":22,"secondary_organization_ids":2345,"content":2346,"image":2347,"status":6,"style":2292,"display_location":1028,"featured":12},29933,[22],"<p>Please note, there are <strong>no elections in Abington on Tuesday, November 4, 2025</strong>. Abington is holding a special election to fill its vacant Select Board seat on Saturday, November 15, 2025. <a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/article/2510628">Read more about the Special Election.</a> </p>",{"url":79,"alt_text":79},{"id":2349,"secondary_organization_id":22,"secondary_organization_ids":2350,"content":2351,"image":2352,"status":6,"style":2292,"display_location":1028,"featured":12},29934,[22],"<p>Abington is holding a special election to fill its vacant Select Board seat on Saturday, November 15, 2025. Early/Absentee voting is available. <a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/article/2510628">Read more about the special election.</a></p>",{"url":79,"alt_text":79},{"id":2354,"secondary_organization_id":22,"secondary_organization_ids":2355,"content":2356,"image":2357,"status":6,"style":2292,"display_location":1028,"featured":12},30313,[22],"<p>A Message from the Assessors’ Office:&nbsp;Public Disclosure of FY2026 Proposed Assessed Values&nbsp;Pending Preliminary Certification&nbsp;<a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/article/2538565">are now available</a>.</p>",{"url":79,"alt_text":79},{"id":2359,"secondary_organization_id":22,"secondary_organization_ids":2360,"content":2361,"image":2362,"status":6,"style":2292,"display_location":1028,"featured":12},30975,[22],"<p>The Town of Abington offices will be closed on Thursday, November 27 in recognition of the Thanksgiving Holiday. Please note, trash and recycling will not be collected on 11/27. Thursday routes will be collected on Friday, and Friday routes will be collected on Saturday.</p>",{"url":79,"alt_text":79},{"id":2364,"secondary_organization_id":22,"secondary_organization_ids":2365,"content":2366,"image":2367,"status":6,"style":2292,"display_location":1028,"featured":12},33061,[22],"<p><strong>Please note Abington Town Hall's holiday schedule:</strong></p><p> December 24, 25, and 26: Closed</p><p> December 31: 8:30AM - 12:00PM</p><p>January 1 and 2: Closed</p><p><strong>Property Tax Reminder</strong></p><p>Residents who wish to pay their property tax bills before the end of the year must submit payment by 12:00 PM on December 31.</p>",{"url":79,"alt_text":79},{"id":2369,"secondary_organization_id":22,"secondary_organization_ids":2370,"content":2371,"image":2372,"status":6,"style":2292,"display_location":1028,"featured":12},35687,[22],"<p>Due to the winter storm earlier this week, trash pick up for all residents is delayed by one day. </p>",{"url":79,"alt_text":79},{"id":2374,"secondary_organization_id":22,"secondary_organization_ids":2375,"content":2376,"image":2377,"status":6,"style":2292,"display_location":1028,"featured":12},38428,[22],"<p>🚨 Abington Town Offices, Abington Public Library, and  Senior Center* (normal operations) will be closed on Tuesday, February 24, 2026.</p><p><strong>**Emergency Shelter Update:</strong></p><p>The Emergency Shelter at the Senior Center will remain open until 12:00 p.m. on Tuesday, February 24th. Additionally, the Abington Police Department Community Room is available if needed.</p><p><strong>Trash &amp; Recycling Update:</strong><br>• Monday routes will be picked up next Monday, March 2.<br>• Tuesday routes will be picked up on Wednesday, February 25<br>• All other routes are delayed one day</p><p>STATE OF EMERGENCY DECLARED – TOWN OF ABINGTON</p><p><a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/article/2722324" relative-link="">Read more about the actions implemented</a>, including closures, parking bans, and emergency shelter.<br></p>",{"url":79,"alt_text":79},{"id":2379,"secondary_organization_id":22,"secondary_organization_ids":2380,"content":2381,"image":2382,"status":6,"style":2292,"display_location":1028,"featured":12},44557,[22],"<p><span>Town Hall will be closed on Friday, July 3rd in observance of July 4th. Friday Trash pick-up will not be affected.</span></p>",{"url":79,"alt_text":79},{"id":2384,"secondary_organization_id":22,"secondary_organization_ids":2385,"content":2386,"image":2387,"status":6,"style":2292,"display_location":1028,"featured":12},44178,[22],"<p>Town Offices are closed on Friday, June 19, 2026, in observance of the Juneteenth holiday. Town offices will reopen for standard hours on Monday, June 22. Trash will not be collected on Friday, June 19th. Residents with a Friday pick-up day will have a one-day delay and will be collected on Saturday, June 20th.</p>",{"url":79,"alt_text":79},{"id":2389,"secondary_organization_id":22,"secondary_organization_ids":2390,"content":2391,"image":2392,"status":6,"style":2292,"display_location":1028,"featured":12},45787,[22],"<p><span>The Massachusetts Department of Environmental Protection has issued a Water Supply Emergency Declaration for the Abington &amp; Rockland Joint Water Works water system. <strong>Reservoirs are critically low. </strong>Mandatory water use restrictions are in place.&nbsp; Please help to conserve water by shutting off irrigation systems and abiding by the Level 4 Water Use Restriction.</span></p><p><span><br><strong>Level Four Watering Ban </strong>- outdoor watering ban. All outdoor water use is prohibited for all uses. </span><a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/article/3053680"><span>Read to learn more. </span></a></p>",{"url":79,"alt_text":79},{"id":2394,"secondary_organization_id":22,"secondary_organization_ids":2395,"content":2396,"image":2397,"status":1123,"style":2292,"display_location":1028,"featured":12},47609,[22],"<p>Effective immediately, the Treasurer/Collector's Office at Town Hall will no longer accept in-person water and sewer bill payments.</p><p>In-person payments must now be dropped off directly at the appropriate office:</p><p><strong>Water bills</strong> — Joint Water Board Office, 366 Centre Avenue, Rockland<br>Hours: Monday–Friday, 8:00 AM–3:30 PM</p><p><strong>Sewer bills</strong> — Abington Sewer Department, 350 Summer Street, Abington</p><p>Online and mailed payments are not affected and will continue to be processed as usual.</p>",{"url":79,"alt_text":79},{"id":2399,"secondary_organization_id":22,"secondary_organization_ids":2400,"content":2401,"image":2402,"status":1123,"style":2403,"display_location":1028,"featured":12},48820,[22],"<p><a target="_self" rel="noopener noreferrer nofollow" href="https://www.abingtonma.gov/article/3198737">Early Voting Hours for the November Statewide Election are now available!</a></p><p>Sat, Oct 17: 10 AM-4 PM<br>Mon, Oct 19: 10 AM-3 PM<br>Tue, Oct 20: 10 AM-3 PM<br>Wed, Oct 21: 10 AM-3 PM<br>Thu, Oct 22: 10 AM-3 PM<br>Fri, Oct 23: 9 AM-12 PM<br>Sat, Oct 24: 10 AM-4 PM</p><p>Questions? Please call us at 781-982-2112 or email <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:lmadams@abingtonma.gov">lmadams@abingtonma.gov</a>. We’re here to help!</p>",{"url":79,"alt_text":79},"light_box",["EmptyRef",1855],{"hasSections":2406,"pageFilters":2407,"allEvents":2410,"fetchingEvents":2413,"sections":2415,"filters":2418,"selectedCalendars":2421,"selectedFilters":2424,"selectedFilter":2427,"currentView"